const Icons = (() => {
  const NS = 'http://www.w3.org/2000/svg';
  // One hidden <svg> holds every icon as a <symbol>; markup anywhere uses <use href="#i-name">.
  function inject() {
    if (document.getElementById('ui-icon-sprite')) return;
    const sym = Object.entries(UI_ICONS).map(([n, [vb, body]]) => `<symbol id="i-${n}" viewBox="${vb}">${body}</symbol>`).join('');
    const holder = document.createElement('div');
    holder.innerHTML = `<svg xmlns="${NS}" id="ui-icon-sprite" aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden">
      <defs>
        <linearGradient id="g-gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff3c4"/><stop offset=".5" stop-color="#ffcf4d"/><stop offset="1" stop-color="#d98a00"/></linearGradient>
        <linearGradient id="g-cyan" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#e6fbff"/><stop offset=".5" stop-color="#5fd8ff"/><stop offset="1" stop-color="#2a7de1"/></linearGradient>
        <linearGradient id="g-rose" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffe0ef"/><stop offset=".5" stop-color="#ff5fa8"/><stop offset="1" stop-color="#b5179e"/></linearGradient>
      </defs>${sym}</svg>`;
    document.body.prepend(holder.firstElementChild);
  }
  const has = (n) => Object.prototype.hasOwnProperty.call(UI_ICONS, n);
  const svg = (name, cls = '') => has(name) ? `<svg class="gi ${cls}" aria-hidden="true" focusable="false"><use href="#i-${name}"></use></svg>` : '';

  // Emoji still used inside game text (toasts, comic scenes, titles) → matching icon.
  const EMOJI = {
    '⚡': 'energy', '🍔': 'hunger', '💧': 'water', '📖': 'prep', '💬': 'social', '🏃': 'run', '💰': 'wallet', '💵': 'item-money',
    '🎯': 'objective', '📱': 'phone', '🗺️': 'map', '🗺': 'map', '🗓️': 'calendar', '🗓': 'calendar', '☀️': 'sun', '☀': 'sun', '🌙': 'moon',
    '🎒': 'backpack', '⏳': 'wait', '💤': 'sleep', '⏰': 'alarm', '📣': 'megaphone', '❌': 'miss', '✅': 'check', '🪪': 'item-id_card',
    '🏏': 'cricket', '📝': 'exam', '🏫': 'school', '🏛️': 'school', '🏛': 'school', '🎸': 'guitar', '🎤': 'mic', '🎓': 'campex', '🏆': 'trophy',
    '🏀': 'basketball', '🎆': 'firework', '💔': 'broken-heart', '😵‍💫': 'dizzy', '😵': 'dizzy', '🥱': 'sleepy', '✨': 'sparkles', '🍛': 'curry',
    '💻': 'laptop', '⏩': 'fastforward', '🌟': 'star', '📚': 'books', '🦋': 'butterfly', '💪': 'fitness', '😬': 'lock', '📋': 'report',
    '📓': 'item-notebook', '🖊️': 'item-pen', '🖊': 'item-pen', '🧮': 'item-calculator', '🥼': 'item-lab_coat', '👟': 'item-sports_kit',
    '📘': 'item-textbook', '💾': 'item-usb', '🥟': 'item-snack', '☕': 'item-tea', '🍎': 'item-fruit',
  };
  const EMOJI_RE = /(?:\p{Extended_Pictographic}(?:\uFE0F)?(?:\u200D\p{Extended_Pictographic}(?:\uFE0F)?)*)/gu;
  const fromEmoji = (e) => EMOJI[e] || EMOJI[e.replace(/\uFE0F/g, '')] || null;
  // Leading emoji of a message → { icon, text } (text without the emoji).
  function split(msg) {
    const m = /^\s*((?:\p{Extended_Pictographic}(?:\uFE0F)?(?:\u200D\p{Extended_Pictographic}(?:\uFE0F)?)*))\s*/u.exec(msg);
    if (!m) return { icon: null, text: msg };
    return { icon: fromEmoji(m[1]), text: msg.slice(m[0].length) };
  }
  // Replace every known emoji in an HTML string with its icon; unknown ones are removed.
  const iconize = (html, cls = 'inline') => html.replace(EMOJI_RE, (e) => { const n = fromEmoji(e); return n ? svg(n, cls) : ''; });
  const strip = (s) => s.replace(EMOJI_RE, '').replace(/\s{2,}/g, ' ').trim();
  const item = (id, cls = '') => svg('item-' + id, cls) || svg('backpack', cls);

  if (document.body) inject(); else document.addEventListener('DOMContentLoaded', inject);
  return { svg, item, fromEmoji, split, iconize, strip, has, inject };
})();
